shellCommands.command:
for t in light dark; do echo "== $t"; grep -o "\.g-root_theme_$t{[^}]*}" styles/styles.css | head -c 0; done; node -e '
const css=require("fs").readFileSync("styles/styles.css","utf8");
for (const t of ["light","dark"]) {
  const re=new RegExp("\\.g-root_theme_"+t+"\\s*\\{([^}]*)\\}","g"); let m, body="";
  while((m=re.exec(css))) body+=m[1];
  const get=n=>{const r=new RegExp("--"+n+":\\s*([^;]+)");const x=body.match(r);return x&&x[1]};
  console.log(t, ["g-color-base-background","g-color-text-primary","g-color-text-secondary","g-color-text-hint","g-color-line-generic","g-color-base-float","g-color-base-generic","g-color-line-generic-solid","g-color-private-white-1000-solid","g-color-private-black-1000-solid"].map(n=>n+"="+get(n)).join("\n  "));
}'; grep -c "g-root_theme" styles/styles.css; ls /home/sandbox/workspace/__agent_eval__; which chromium google-chrome 2>/dev/null; ls ~/.cache/ms-playwright 2>/dev/null

sed -i 's/const MARGIN = {top: 12, right: 112,/const MARGIN = {top: 12, right: 128,/' src/LineChart.tsx && mkdir -p /tmp/ssrcheck && cat > /tmp/ssrcheck/ssr.tsx <<'EOF'
import React from 'react';
import {renderToString} from 'react-dom/server';
import {ThemeProvider, useThemeType} from '@gravity-ui/uikit';
import {App} from '/home/sandbox/workspace/src/App';
import {SERIES_COLORS} from '/home/sandbox/workspace/src/palette';
function Probe() { const t = useThemeType(); return <i data-colors={SERIES_COLORS[t].join(',')} />; }
for (const theme of ['light', 'dark', 'dark-hc', 'system'] as const) {
  const html = renderToString(<ThemeProvider theme={theme}><Probe /><App /></ThemeProvider>);
  console.log(theme, html.length, html.match(/data-colors="[^"]+"/)?.[0], html.match(/g-root_theme_[a-z-]+/)?.[0]);
}
EOF
npx vite-node /tmp/ssrcheck/ssr.tsx 2>&1 | grep -v useLayoutEffect | tail -15
